import{_ as a,a as e,o as r,a4 as o}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Cart","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/cart/index.md","filePath":"api/graphql-api/shop/cart/index.md","lastUpdated":1784902076000}'),i={name:"api/graphql-api/shop/cart/index.md"};function n(d,t,h,p,s,c){return r(),e("div",null,t[0]||(t[0]=[o('<h1 id="cart" tabindex="-1">Cart <a class="header-anchor" href="#cart" aria-label="Permalink to &quot;Cart&quot;">​</a></h1><p>The Cart menu is the shopping cart — creating a cart, adding and updating items, applying coupons, and reading the current cart with its totals. It is the first half of the buying flow; once the cart is ready you move on to <a href="/api/graphql-api/shop/checkout/">Checkout</a>.</p><h2 id="how-the-cart-token-works" tabindex="-1">How the cart token works <a class="header-anchor" href="#how-the-cart-token-works" aria-label="Permalink to &quot;How the cart token works&quot;">​</a></h2><p>Creating a cart returns a <strong>cart token</strong>. That token identifies the cart on every subsequent cart operation, so a guest can build up a cart without being signed in. A signed-in customer can also keep a cart; the <strong>merge</strong> mutation combines a guest cart into the customer&#39;s cart after they log in, so nothing is lost.</p><h2 id="typical-sequence" tabindex="-1">Typical sequence <a class="header-anchor" href="#typical-sequence" aria-label="Permalink to &quot;Typical sequence&quot;">​</a></h2><ol><li>Create a cart (returns the cart token).</li><li>Add items (and update or remove them as the shopper changes their mind).</li><li>Optionally apply a coupon, and remove it again if needed.</li><li>Read the cart at any point to show the current items and totals.</li></ol><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/queries/get-cart.html">Get Cart</a></td><td><code>createReadCart</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/create-cart.html">CreateCart</a></td><td><code>createCart</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/add-to-cart.html">AddToCart</a></td><td><code>addItemToCart</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/update-cart-item.html">UpdateCartItem</a></td><td><code>updateItemToCart</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/remove-cart-item.html">RemoveCartItem</a></td><td><code>removeCartItem</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/merge-cart.html">Merge Cart</a></td><td><code>mergeCart</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/apply-coupon.html">ApplyCoupon</a></td><td><code>applyCoupon</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/remove-coupon.html">RemoveCoupon</a></td><td><code>removeCoupon</code> mutation</td></tr></tbody></table><p>Cart operations are keyed by the cart token; a guest needs only the storefront key, while a signed-in customer also sends their Bearer token. See <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',9)]))}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
